import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, mix, float, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader('/prism-mock/home/nodes/orb-decor.png');
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
  }

  const inkColor = vec3(0x16 / 255, 0x16 / 255, 0x1d / 255);
  const surfaceColor = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255);

  const uvNode = uv();

  // engineered gradient surface, top-to-bottom, subtle
  const gradientMix = mix(surfaceColor, inkColor, uvNode.y);

  // subtle grain via a cheap pseudo-random function based on uv
  const grainSeed = uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233)).sin().mul(43758.5453);
  const grain = grainSeed.fract().sub(0.5).mul(0.04);

  const baseColor = gradientMix.add(vec3(grain, grain, grain));

  if (map) {
    const texColor = texture(map, uvNode);
    material.colorNode = mix(baseColor, texColor.rgb, texColor.a);
    material.opacityNode = float(1.0);
  } else {
    material.colorNode = baseColor;
  }

  const mesh = new THREE.Mesh(geometry, material);

  mesh.position.set(0, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.name = 'hub-collection-card-2-decor';

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return mesh;
}
